function chooseView(name,{source="manual"}={}){if(walk.active)exitWalk({restore:false});if(activeDream)exitDream({restore:false});if(host.dataset.ready==="true"&&window.closePortraitGallery)window.closePortraitGallery();const cfg=viewConfig[name];if(!cfg)return;activeView=name;document.getElementById('districtTitle').textContent=cfg.title;document.getElementById('districtDescription').textContent=cfg.text;baseRadius=fittingRadius();
const to={target:new THREE.Vector3(...cfg.target),theta:cfg.theta,phi:cfg.phi,radius:cfg.radius?cfg.radius*Math.max(1,.93/(host.clientWidth/host.clientHeight)):baseRadius};
if(host.dataset.ready==='true'&&!motionPaused&&!motionPreference.matches){const distance=target.distanceTo(to.target);cameraJourney={from:{target:target.clone(),theta,phi,radius},to,angle:Math.atan2(Math.sin(to.theta-theta),Math.cos(to.theta-theta)),started:performance.now(),duration:source==="tour"?1600:Math.min(2300,1350+distance*1.3)};}
else{cameraJourney=null;target.copy(to.target);theta=to.theta;phi=to.phi;radius=to.radius;}
document.querySelectorAll('[data-view]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.view===name)));syncGalleryView(name);render();window.dispatchEvent(new CustomEvent("changan-view",{detail:{name,source}}));}
function syncMotionButton(){const button=document.getElementById('motion');button.setAttribute('aria-pressed',String(motionPaused));button.textContent=motionPaused?'继续动态':'暂停动态';}
document.getElementById('motion').onclick=()=>{motionPaused=!motionPaused;if(motionPaused)cancelCameraJourney();syncMotionButton();render();};
