syncMotionButton();
function startWaterAnimation(){if(animationStarted)return;animationStarted=true;let previous=performance.now(),nextCityFrame=0,lastCityBudget=-1;document.addEventListener('visibilitychange',()=>{previous=performance.now();nextCityFrame=0;lastCityBudget=-1;resetWalkingDrawSampling();});
function frame(now){requestAnimationFrame(frame);const dt=Math.min(.15,Math.max(0,(now-previous)/1000));previous=now;if(document.hidden||document.body.classList.contains('exhibition')||document.body.classList.contains('reading-notes')){if(flushCityRender(now))streetRouteRenderPending=false;nextCityFrame=now;lastCityBudget=-1;return;}
if(!motionPaused)motionSeconds+=dt;const humanMoved=updateCityHumanLife(dt,now),walkMoved=updateWalk(dt),routeMoved=updateStreetRouteForFrame(now),mainMoved=updateMainNightMarker(),nightMoved=updateCityNight(dt,now),storyMoved=updateCityStoryNearby(now),performanceMoved=updateTangPerformance(dt),journeyMoved=updateJourneyScene(now),cameraMoved=updateCameraJourney(now);if(!cameraMoved&&!walkMoved&&!performanceMoved&&!journeyMoved&&!nightMoved&&!humanMoved&&!mainMoved&&!routeMoved&&motionPaused){if(flushCityRender(now))streetRouteRenderPending=false;nextCityFrame=now;lastCityBudget=-1;return;}const cityBudget=walk.active?(quality.light?1000/30:0):cameraMoved?(quality.light?50:1000/30):quality.frameMs;if(cityBudget!==lastCityBudget){nextCityFrame=now;lastCityBudget=cityBudget;}if(cityBudget>0&&now+1<nextCityFrame){if(flushCityRender(now,!motionPaused||walkMoved))streetRouteRenderPending=false;return;}if(cityBudget>0)nextCityFrame+=Math.max(1,Math.floor((now-nextCityFrame)/cityBudget)+1)*cityBudget;else nextCityFrame=now;
if(!motionPaused){if(activeDream)updateDream(motionSeconds);else{updateSpray(motionSeconds);updateAtmosphere(motionSeconds);updateBoat(motionSeconds);updateCityLife(motionSeconds);}}render();if(flushCityRender(now,true))streetRouteRenderPending=false;}
requestAnimationFrame(frame);}
