// Input is kept here; the final bridge integration supplies real body/height
// collision and falling. Clearing controls pauses flight instead of cancelling it.
const WALK_JUMP_GRAVITY=16,WALK_JUMP_SPEED=7.2;
let walkingJumpPhysics=null;
walk.jumpHeight=0;walk.jumpVelocity=0;
function resetWalkingJump(){
 if(walkingJumpPhysics){if(walk.active)return false;return walkingJumpPhysics.reset();}
 const changed=walk.jumpHeight!==0||walk.jumpVelocity!==0;
 walk.jumpHeight=0;walk.jumpVelocity=0;if(changed)render();
}
function startWalkingJump(){
 if(walkInputBlocked()||document.hasFocus?.()===false)return false;
 if(walkingJumpPhysics){const started=walkingJumpPhysics.start();if(started)render();return started;}
 if(walk.jumpHeight!==0||walk.jumpVelocity!==0)return false;
 walk.jumpVelocity=WALK_JUMP_SPEED;render();return true;
}
function updateWalkingJump(dt){
 if(walkingJumpPhysics)return walkingJumpPhysics.update(dt);
 if(walk.jumpHeight===0&&walk.jumpVelocity===0)return false;
 const elapsed=Math.min(.15,Math.max(0,Number.isFinite(dt)?dt:0));
 // Exact constant-gravity integration avoids frame-rate-dependent jump height.
 const height=walk.jumpHeight+walk.jumpVelocity*elapsed-WALK_JUMP_GRAVITY*elapsed*elapsed*.5;
 const velocity=walk.jumpVelocity-WALK_JUMP_GRAVITY*elapsed;
 if(height<=0&&velocity<=0){walk.jumpHeight=0;walk.jumpVelocity=0;}
 else{walk.jumpHeight=Math.max(0,height);walk.jumpVelocity=velocity;}
 // The landing frame also needs a draw to restore the normal eye height.
 return true;
}
