  walk.keys.clear();walk.stickX=walk.stickY=0;const look=walk.lookPointer,stick=stickPointer;walk.lookPointer=null;stickPointer=null;
  for(const [node,id] of [[host,look],[document.getElementById('walkJoystick'),stick]])if(id!==null&&node?.hasPointerCapture(id))node.releasePointerCapture(id);
