host.addEventListener('pointerdown',e=>{if(e.pointerType==='mouse'){prepareWalkingMouseLook(e);return;}if(walkInputBlocked()||e.button>0||walk.lookPointer!==null)return;walk.lookPointer=e.pointerId;walk.lookX=e.clientX;walk.lookY=e.clientY;walk.lookTouch=e.pointerType==='touch';host.setPointerCapture(e.pointerId);host.focus({preventScroll:true});});
