function journeyMarkerState(){const distance=journeyMarkerStep&&walk.active?Math.hypot(walk.x-journeyMarkerGroup.position.x,walk.z-journeyMarkerGroup.position.z):null,objectY={poem:1.56,score:1.56,ribbon:1.65,chime:3,lantern:2.1,stone:1.8}[journeyMarkerStep?.object]||2,screen=new THREE.Vector3(journeyMarkerGroup.position.x,journeyMarkerGroup.position.y+objectY,journeyMarkerGroup.position.z).project(camera),rect=renderer.domElement.getBoundingClientRect();return {visible:!!journeyMarkerStep&&!activeDream,stepId:journeyMarkerStep?.id||null,place:journeyMarkerStep?.place||null,x:journeyMarkerGroup.position.x,z:journeyMarkerGroup.position.z,distance,nearby:distance!==null&&distance<=3.2&&!activeDream&&!document.body.classList.contains("main-tracking"),screen:{x:rect.left+(screen.x+1)*rect.width/2,y:rect.top+(1-screen.y)*rect.height/2}};}
function setJourneyMarker(step){
 journeyMarkerStep=step&&journeyLocations[step.place]?step:null;
 while(journeyMarkerGroup.children.length){const object=journeyMarkerGroup.children[0];journeyMarkerGroup.remove(object);object.traverse(child=>{if(child.isMesh)child.material.dispose();});}
 if(!journeyMarkerStep){journeyMarkerGroup.visible=false;render();return;}
 const [x,z]=journeyLocations[step.place];journeyMarkerGroup.position.set(x,walkMap.groundY,z);journeyMarkerGroup.visible=!activeDream;
 const box=(px,py,pz,w,h,d,color,glow=false)=>{const material=new THREE.MeshStandardMaterial({color,roughness:.85,...(glow?{emissive:color,emissiveIntensity:.65}:{})}),mesh=new THREE.Mesh(boatGeometry,material);mesh.position.set(px,py,pz);mesh.scale.set(w,h,d);journeyMarkerGroup.add(mesh);return mesh;};
 box(0,.7,0,.5,1.4,.5,'#71634c');box(0,1.43,0,1.45,.12,1,'#a48a5f');
 if(step.object==='poem'||step.object==='score'){box(0,1.54,0,1.15,.08,.73,'#e1d9b9');for(let i=0;i<4;i++)box(-.1,1.588,-.22+i*.12,.65,.01,.025,'#534b43');if(step.object==='score')for(let i=0;i<3;i++)box(-.32+i*.2,1.606,-.15+i*.12,.07,.015,.07,'#765649');}
 else if(step.object==='chime'){box(0,2.45,0,.12,1.9,.12,'#637359');box(0,3.35,0,1.1,.12,.12,'#a0a085');for(let i=-1;i<=1;i++)box(i*.32,2.95-i*.12,0,.13,.62+i*.1,.13,'#c0b397',true);}
 else if(step.object==='lantern'){box(0,2.13,0,.7,1.12,.68,'#dba268',true);box(0,2.74,0,.82,.12,.8,'#584c3c');box(0,1.52,0,.82,.12,.8,'#584c3c');}
 else if(step.object==='ribbon'){for(let i=0;i<5;i++)box(-.5+i*.22,1.64+Math.sin(i*.8)*.12,0,.25,.12,.22,'#c78680');box(0,1.93,0,.1,.66,.1,'#b0966d');}
 else{box(0,1.78,0,.76,.45,.56,'#91a39b');box(.15,2.02,0,.48,.17,.4,'#b2b9a5');}
 const glow=box(0,3.78,0,.17,.17,.17,'#e9d19b',true);glow.rotation.z=Math.PI/4;glow.name='clue-light';
 const light=new THREE.PointLight('#ffe0ad',7,9,2);light.position.set(0,2.7,0);journeyMarkerGroup.add(light);
 window.dispatchEvent(new CustomEvent('changan-journey-near',{detail:journeyMarkerState()}));render();
}
function collectJourneyMarker(){if(document.body.classList.contains("main-tracking"))return false;const state=journeyMarkerState();if(!state.nearby||!walk.active||document.querySelector('dialog[open]')||document.body.classList.contains('exhibition'))return false;clearWalkInput();window.dispatchEvent(new CustomEvent('changan-journey-collect',{detail:{stepId:journeyMarkerStep.id}}));return true;}
window.changanJourneyMarker=setJourneyMarker;window.changanJourneyMarkerState=journeyMarkerState;window.changanJourneyCollect=collectJourneyMarker;
host.addEventListener('pointerdown',event=>{if(event.button===0&&event.target===renderer.domElement)journeyPointer={id:event.pointerId,x:event.clientX,y:event.clientY};});
host.addEventListener('pointerup',event=>{const start=journeyPointer;journeyPointer=null;if(!start||start.id!==event.pointerId||Math.hypot(event.clientX-start.x,event.clientY-start.y)>8||!walk.active||!journeyMarkerGroup.visible)return;const rect=renderer.domElement.getBoundingClientRect();journeyPointerPosition.set((event.clientX-rect.left)/rect.width*2-1,-(event.clientY-rect.top)/rect.height*2+1);if(walkingMouseLookLocked())journeyPointerPosition.set(0,0);journeyRaycaster.setFromCamera(journeyPointerPosition,camera);if(journeyRaycaster.intersectObject(journeyMarkerGroup,true).length)collectJourneyMarker();});
