// A bounded dream sequence owns only the orbit it changes, and yields to input.
const journeySceneRun={running:false,id:null,elapsed:0,line:-1,startedAt:0,saved:null,reduced:false,lastNotice:0};
function journeySceneNotice(extra={}){window.dispatchEvent(new CustomEvent('changan-journey-scene',{detail:{running:journeySceneRun.running,id:journeySceneRun.id,elapsed:journeySceneRun.elapsed,line:journeySceneRun.line,duration:21,...extra}}));}
function stopJourneyScene({restore=true,completed=false}={}){if(!journeySceneRun.running)return;const id=journeySceneRun.id;journeySceneRun.running=false;if(typeof setJourneyGesture==='function')setJourneyGesture(id,0);if(restore&&activeDream===id)restoreOrbit(journeySceneRun.saved);journeySceneRun.saved=null;document.body.classList.remove('journey-playing');window.ChanganCharacterSound?.stop();journeySceneNotice({completed});render();}
function startJourneyScene({id,title,lines}){if(!dreamViews[id]||!Array.isArray(lines)||lines.length!==3||document.hidden)return false;stopJourneyScene();enterDream(id);cancelCameraJourney();Object.assign(journeySceneRun,{running:true,id,elapsed:0,line:0,startedAt:performance.now(),saved:rememberOrbit(),reduced:matchMedia('(prefers-reduced-motion: reduce)').matches,lastNotice:0});document.body.classList.add('journey-playing');journeySceneNotice({title,lines});render();return true;}
function updateJourneyScene(now){
 if(journeyMarkerStep&&now-journeyMarkerLastNotice>200){journeyMarkerLastNotice=now;window.dispatchEvent(new CustomEvent('changan-journey-near',{detail:journeyMarkerState()}));}
 if(!journeySceneRun.running)return false;
 if(document.hidden||activeDream!==journeySceneRun.id||document.querySelector('dialog[open]')||document.body.classList.contains('exhibition')){stopJourneyScene({restore:activeDream===journeySceneRun.id});return true;}
 journeySceneRun.elapsed=Math.min(21,Math.max(0,(now-journeySceneRun.startedAt)/1000));const progress=journeySceneRun.elapsed/21,index=Math.min(2,Math.floor(journeySceneRun.elapsed/7));
 if(!journeySceneRun.reduced){const base=journeySceneRun.saved,ease=progress*progress*(3-2*progress);theta=base.theta+Math.sin(progress*Math.PI)*.19;phi=base.phi-Math.sin(progress*Math.PI)*.04;radius=base.radius*(1-.28*Math.sin(progress*Math.PI));if(typeof setJourneyGesture==='function')setJourneyGesture(journeySceneRun.id,progress);}
 if(index!==journeySceneRun.line||now-journeySceneRun.lastNotice>200||progress===1){journeySceneRun.line=index;journeySceneRun.lastNotice=now;journeySceneNotice();}
 if(progress===1)stopJourneyScene({completed:true});return true;
}
window.changanStartJourneyScene=startJourneyScene;window.changanStopJourneyScene=()=>stopJourneyScene();window.changanJourneySceneState=()=>({running:journeySceneRun.running,id:journeySceneRun.id,elapsed:journeySceneRun.elapsed,line:journeySceneRun.line,reduced:journeySceneRun.reduced});
