document.addEventListener('keydown',event=>{if(!journeySceneRun.running||document.querySelector('dialog[open]'))return;if(event.key==='Escape'){event.preventDefault();event.stopImmediatePropagation();stopJourneyScene();}else if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','+','-'].includes(event.key))stopJourneyScene();},{capture:true});
