// The night belongs to the city; character dream scenes keep their own lighting.
const cityNightPhases=[
 {id:'dusk',name:'入夜',caption:'檐下初灯，街声渐起。',sky:'#273240',fog:'#435057',sun:'#e5c4ab',power:1.75,ambient:1.72,windows:.72,lamps:.85,stars:.32,crowd:[0,1,3,5]},
 {id:'market',name:'灯市',caption:'一城灯火，照见往来的人。',sky:'#091d27',fog:'#18353d',sun:'#a9bfee',power:1.9,ambient:1.65,windows:1,lamps:1,stars:.65,crowd:[0,1,2,3,4,5,6]},
 {id:'quiet',name:'夜深',caption:'巷声渐远，留灯待归人。',sky:'#081322',fog:'#1a2a3a',sun:'#91abd8',power:1.45,ambient:1.4,windows:.36,lamps:.68,stars:.83,crowd:[0,6]},
 {id:'dawn',name:'将晓',caption:'远山浮白，炉火还温。',sky:'#40545d',fog:'#627478',sun:'#e8ceb0',power:2.05,ambient:1.95,windows:.22,lamps:.38,stars:.12,crowd:[1,3,6]}
];
const cityNight={index:0,elapsed:0,automatic:!matchMedia('(prefers-reduced-motion: reduce)').matches,blend:1,from:0,lastNotice:0};
const citySkyLight=scene.children.find(light=>light.isHemisphereLight),cityStarPoints=scene.children.find(points=>points.geometry===starGeometry);
const cityLampLights=scene.children.filter(light=>light.isPointLight).map(light=>({light,power:light.intensity}));
const nightColorA=new THREE.Color(),nightColorB=new THREE.Color();
function cityNightPaused(){return document.body.classList.contains('arrival-intro')||document.hidden||!!activeDream||motionPaused||!!document.querySelector('dialog[open]')||document.body.classList.contains('exhibition')||document.body.classList.contains('reading-notes');}
function cityNightNotice(){const phase=cityNightPhases[cityNight.index];window.dispatchEvent(new CustomEvent('changan-night-hour',{detail:{...phase,automatic:cityNight.automatic,paused:cityNightPaused(),elapsed:cityNight.elapsed,duration:120}}));}
function applyCityNightAtmosphere(){
 const phase=cityNightPhases[cityNight.index],before=cityNightPhases[cityNight.from],t=cityNight.blend,mix=key=>THREE.MathUtils.lerp(before[key],phase[key],t);
 nightColorA.set(before.sky);nightColorB.set(phase.sky);scene.background.copy(nightColorA.lerp(nightColorB,t));if(cityWeatherMode==='rain')scene.background.lerp(nightColorB.set('#102731'),.35);
 nightColorA.set(before.fog);nightColorB.set(phase.fog);scene.fog.color.copy(nightColorA.lerp(nightColorB,t));
 sunlight.color.copy(nightColorA.set(before.sun).lerp(nightColorB.set(phase.sun),t));sunlight.intensity=mix('power')-rainStrength*.35;
 if(citySkyLight)citySkyLight.intensity=mix('ambient');if(cityStarPoints)cityStarPoints.material.opacity=mix('stars')*(1-rainStrength*.6);
 moon.material.opacity=mix('lamps')*.82;cityLampLights.forEach(({light,power})=>light.intensity=power*mix('lamps'));
 breathingWindows.forEach((item,i)=>item.material.emissiveIntensity=item.intensity*mix('windows')*(motionPaused?1:.97+.03*Math.sin(motionSeconds*.34+i*1.63)));
 breathingLamps.forEach(item=>item.sprite.material.opacity=item.opacity*mix('lamps')*(motionPaused?1:.94+.06*Math.sin(motionSeconds*.43+item.phase)));
}
function setCityNightPhase(id,{automatic=false}={}){const next=cityNightPhases.findIndex(phase=>phase.id===id);if(next<0)return false;cityNight.from=cityNight.index;cityNight.index=next;cityNight.elapsed=0;cityNight.automatic=automatic;cityNight.blend=motionPaused||matchMedia('(prefers-reduced-motion: reduce)').matches?1:0;updateCityLife(motionSeconds);cityNightNotice();render();return true;}
function updateCityNight(dt,now){let changed=false;if(!cityNightPaused()){
 if(cityNight.blend<1){cityNight.blend=Math.min(1,cityNight.blend+dt/2.8);changed=true;}
 if(cityNight.automatic){cityNight.elapsed+=dt;if(cityNight.elapsed>=120){setCityNightPhase(cityNightPhases[(cityNight.index+1)%4].id,{automatic:true});changed=true;}}
 }if(now-cityNight.lastNotice>1000){cityNight.lastNotice=now;cityNightNotice();}return changed;
}
window.changanNightLightFactors=()=>({crowd:cityNightPhases[cityNight.index].crowd});
