function cityStoryMarkerState(){const story=cityStoryDefinitions.find(s=>s.id===cityStoryNear),place=story&&cityStoryLocations[story.type],distance=story&&walk.active?Math.hypot(walk.x-place.point[0],walk.z-place.point[1]):null,point=place?new THREE.Vector3(place.point[0],walkMap.groundY+1.47,place.point[1]).project(camera):null,rect=renderer.domElement.getBoundingClientRect();return {id:story?.id||null,name:story?.name||null,nearby:!!story&&distance<=3.4&&walk.active&&!activeDream&&!journeyMarkerState().nearby&&!window.changanMainNightMarkerState?.().nearby,distance,x:place?.point[0],z:place?.point[1],screen:point?{x:rect.left+(point.x+1)*rect.width/2,y:rect.top+(1-point.y)*rect.height/2}:null};}
function updateCityStoryNearby(now){updateCityHouseNearby(now);cityStoriesRoot.visible=!activeDream;if(now-cityStoryLastNotice<180)return false;cityStoryLastNotice=now;let nearest=null,distance=3.4;for(const story of cityStoryDefinitions){const [x,z]=cityStoryLocations[story.type].point,d=walk.active&&!activeDream?Math.hypot(walk.x-x,walk.z-z):Infinity;if(d<=distance){nearest=story.id;distance=d;}}cityStoryNear=nearest;window.dispatchEvent(new CustomEvent('changan-city-near',{detail:cityStoryMarkerState()}));return false;}
function openNearbyCityStory(id=cityStoryNear){if(window.changanMainNightInteract?.(id))return true;const state=cityStoryMarkerState();if(state.id!==id||!state.nearby||document.querySelector('dialog[open]')||document.body.classList.contains('exhibition'))return false;clearWalkInput();window.dispatchEvent(new CustomEvent('changan-city-open',{detail:{id}}));return true;}
window.changanCityStoryWalk=id=>{const story=cityStoryDefinitions.find(s=>s.id===id);if(!story)return false;enterWalk('story-'+id);updateCityStoryNearby(performance.now()+200);return true;};
window.changanCityStoryMarkerState=cityStoryMarkerState;window.changanCityStoryInteract=openNearbyCityStory;
document.addEventListener('keydown',event=>{if(event.defaultPrevented||event.repeat||event.code!=='KeyE'||['INPUT','SELECT','TEXTAREA','BUTTON'].includes(event.target.tagName))return;if(openNearbyCityStory())event.preventDefault();});
const cityStoryRaycaster=new THREE.Raycaster(),cityStoryPointerPosition=new THREE.Vector2();
host.addEventListener('pointerdown',event=>{if(event.button===0&&event.target===renderer.domElement)cityStoryPointer={id:event.pointerId,x:event.clientX,y:event.clientY};});
host.addEventListener('pointerup',event=>{const start=cityStoryPointer;cityStoryPointer=null;if(!start||start.id!==event.pointerId||Math.hypot(event.clientX-start.x,event.clientY-start.y)>8||!walk.active||activeDream||(journeyMarkerState().nearby&&!document.body.classList.contains('main-tracking')))return;const rect=renderer.domElement.getBoundingClientRect();cityStoryPointerPosition.set((event.clientX-rect.left)/rect.width*2-1,-(event.clientY-rect.top)/rect.height*2+1);if(walkingMouseLookLocked())cityStoryPointerPosition.set(0,0);cityStoryRaycaster.setFromCamera(cityStoryPointerPosition,camera);const hit=cityStoryRaycaster.intersectObject(cityStoriesRoot,true)[0],id=hit?.object.userData.cityStoryIds?.[hit.instanceId];if(id)openNearbyCityStory(id);});
