function cityHumanSyncMemories(){if(!cityHumanMemoriesDirty)return false;cityHumanMemoriesDirty=false;let changed=false;for(const [key,rule] of cityHumanPartRules){const ref=cityHumanRefs.get(key);if(ref){const pose=ref.last?{x:ref.last[0],y:ref.last[1],z:ref.last[2],rx:ref.last[3],ry:ref.last[4],rz:ref.last[5]}:{};changed=cityHumanWrite(ref,{...pose,visible:cityHumanRuleVisible(rule)})||changed;}}return changed;}
