 const props=[],targets=[];
 const add=(group,x,y,z,w,h,d,color,options={})=>{const r={group,x,y,z,w,h,d,color,solid:true,...options};props.push(r);return r;};
 const gallery=(group,x,y,z,w,h,d,color,options={})=>{const p=local(x,z);return add(group,p[0],y,p[1],house.turn%2?d:w,h,house.turn%2?w:d,color,{area:'gallery',...options});};
 const target=(id,name,group,x,y,z,area)=>targets.push({id,name,group,x,y,z,area});
 // Objects stand on the existing two furniture columns, outside the door lane.
 gallery('ledger',2,2.66,1,.86,.13,.74,'paper',{target:'ledger'});
 for(let i=0;i<3;i++)gallery('ledger',2,2.735,.8+i*.14,.62,.014,.025,'ink',{solid:false,target:'ledger'});
