 gallery('paper',-2,3.62,0,.78,.12,.68,'paper',{target:'paper'});
 for(let i=0;i<3;i++)gallery('paper',-2.22+i*.22,3.695,.05,.16,.025,.18,'seal',{solid:false,target:'paper'});
 gallery('shade',2,3.26,0,.72,1.1,.66,'paper',{target:'shade'});
 gallery('shade',2,3.86,0,.94,.12,.84,'wood',{target:'shade'});
 gallery('shade',2,2.69,0,.94,.13,.84,'wood',{target:'shade'});
 gallery('patch',1.625,3.27,.05,.026,.27,.3,'seal',{solid:false,target:'shade'});
 gallery('shutter',2,3.26,.345,.07,.78,.025,'wood',{solid:false,target:'shade'});
