 // The projection is paint/light against the existing rear wall, not a wall
 // inserted in the three-wide passage. Three readable silhouettes accompany text.
 gallery('screen',0,3.35,-.44,2.4,1.5,.025,'screen',{solid:false,target:'shade'});
 gallery('shadow-bridge',0,3.35,-.415,1.64,.12,.03,'ink',{solid:false});
 for(const x of[-.62,.62])gallery('shadow-bridge',x,3.13,-.415,.14,.46,.03,'ink',{solid:false});
 gallery('shadow-bamboo',-.4,3.35,-.415,.1,1.1,.03,'ink',{solid:false});
 gallery('shadow-bamboo',.1,3.35,-.415,.1,.9,.03,'ink',{solid:false});
