function createChanganLanternWalkCollision(layout){
 let ending=null,angle=0,paperTaken=false;
 function pose(){return ending==='send'?{x:93.5,y:layout.groundY,z:243.5,turn:1}:{x:46,y:layout.groundY,z:244,turn:0};}
 function box(p){if(p.group==='shade'&&p.color==='paper'&&angle===1)return{...p,w:p.d,d:p.w};if(p.area!=='ferry')return p;const t=pose();return{...p,x:t.x+(t.turn?p.z:p.x),y:t.y+p.y,z:t.z+(t.turn?-p.x:p.z),w:t.turn?p.d:p.w,d:t.turn?p.w:p.d};}
 const solid=layout.props.filter(p=>p.solid);let batches=[];
 function rebuild(){const groups=new Map();for(const source of solid){if(source.group==='paper'&&paperTaken)continue;const p=box(source);if(!groups.has(p.area))groups.set(p.area,[]);groups.get(p.area).push(p);}batches=[...groups.values()].map(boxes=>({boxes,minX:Math.min(...boxes.map(p=>p.x-p.w/2)),maxX:Math.max(...boxes.map(p=>p.x+p.w/2)),minZ:Math.min(...boxes.map(p=>p.z-p.d/2)),maxZ:Math.max(...boxes.map(p=>p.z+p.d/2)),minY:Math.min(...boxes.map(p=>p.y-p.h/2)),maxY:Math.max(...boxes.map(p=>p.y+p.h/2))}));}
 rebuild();
 function clear(x,z,foot){
  for(const group of batches){if(x+.55<=group.minX+.01||x-.55>=group.maxX-.01||z+.55<=group.minZ+.01||z-.55>=group.maxZ-.01||foot>=group.maxY-.01||foot+3.5<=group.minY+.01)continue;for(const p of group.boxes)if(Math.abs(x-p.x)<.55+p.w/2-.01&&Math.abs(z-p.z)<.55+p.d/2-.01&&foot<p.y+p.h/2-.01&&foot+3.5>p.y-p.h/2+.01)return false;}
  return true;
 }
 function sweepVertical(x,z,from,to){
  if(Math.abs(to-from)<1e-10)return null;
  const steps=Math.max(1,Math.ceil(Math.abs(to-from)/.15));let safe=from;
  for(let i=1;i<=steps;i++){const next=from+(to-from)*i/steps;if(!clear(x,z,next)){let blocked=next;for(let j=0;j<18;j++){const middle=(safe+blocked)/2;if(clear(x,z,middle))safe=middle;else blocked=middle;}return{foot:safe,grounded:to<from};}safe=next;}return null;
 }
 function setState(next){const e=Object.hasOwn(next,'ending')?(['send','keep'].includes(next.ending)?next.ending:null):ending,a=Number.isInteger(next.angle)&&next.angle>=0&&next.angle<=2?next.angle:angle,p=typeof next.paperTaken==='boolean'?next.paperTaken:paperTaken;if(e!==ending||a!==angle||p!==paperTaken){ending=e;angle=a;paperTaken=p;rebuild();}}
 return{clear,sweepVertical,setState,setEnding:value=>setState({ending:value}),pose,boxes:()=>batches.flatMap(g=>g.boxes.map(p=>({...p})))};
}
