  const root=new THREE.Group(),gallery=new THREE.Group(),shore=new THREE.Group(),ferry=new THREE.Group();
  root.name='borrowed-lantern-in-city';gallery.name='lantern-gallery-investigation';shore.name='lantern-moonbridge-echo';ferry.name='lantern-tangible-ferry';
  root.add(gallery,shore);shore.add(ferry);scene.add(root);
  const colors={paper:'#dfd1a8',ink:'#343a37',wood:'#60503c',seal:'#a8604e',iron:'#8c9690',warm:'#e8bd73',screen:'#bba775'},materials=new Map(),records=[];
  const groups=new Map();let current=window.ChanganLanternWalk?.snapshot(),lastRevision=-1,lastNotice=-Infinity,lastTarget=null,disposed=false;
