  function inside(){const dx=walk.x-house.center.x,dz=walk.z-house.center.z,t=house.turn,x=t===0?dx:t===1?-dz:t===2?-dx:dz,z=t===0?dz:t===1?dx:t===2?-dz:-dx;return Math.abs(x)<1.4&&z>=.15&&z<=house.localDepth+.2;}
  function eligible(t){return walk.active&&!activeDream&&!walk.swimming&&walk.grounded&&t.area===(inside()?'gallery':'shore')&&Math.hypot(walk.x-t.x,walk.z-t.z)<=4.8;}
  function facing(t){const dx=t.x-walk.x,dz=t.z-walk.z,d=Math.hypot(dx,dz);return d<.2?1:(dx*Math.sin(walk.yaw)+dz*Math.cos(walk.yaw))/d;}
