   for(const m of groups.get('shade')||[])if(m.material===material('paper')){m.scale.set(current.angle===1?(house.turn%2?.72:.66):(house.turn%2?.66:.72),m.scale.y,current.angle===1?(house.turn%2?.66:.72):(house.turn%2?.72:.66));}
   const pivot=layout.local(2,0),theta=current.angle*Math.PI/2,c=Math.cos(theta),s=Math.sin(theta);for(const{p,mesh}of records)if(p.group==='shutter'||p.group==='patch'){const x=p.x-pivot[0],z=p.z-pivot[1];mesh.position.set(pivot[0]+x*c+z*s,p.y,pivot[1]-x*s+z*c);mesh.rotation.y=theta;}
   for(const m of groups.get('paper')||[])m.visible=!current.discoveries.includes('paper');
   collision.setState({ending:current.lastEnding,angle:current.angle,paperTaken:current.discoveries.includes('paper')});const pose=collision.pose();ferry.position.set(pose.x,pose.y,pose.z);ferry.rotation.y=pose.turn*Math.PI/2;
